// Datei → base64 + Claude-Content-Block (PDF/Bild nativ; docx/xlsx vorab
// über Graph als PDF konvertieren: /content?format=pdf).
const meta = $('Einzeln').item.json;
const bin = await this.helpers.getBinaryDataBuffer(0, 'data');
const b64 = bin.toString('base64');
const ext = (meta.file_type || '').toLowerCase();
const imageTypes = { png: 'image/png', jpg: 'image/jpeg', jpeg: 'image/jpeg', gif: 'image/gif', webp: 'image/webp' };
let block;
if (imageTypes[ext]) {
  block = { type: 'image', source: { type: 'base64', media_type: imageTypes[ext], data: b64 } };
} else {
  block = { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } };
}
return [{ json: { meta, contentBlock: block } }];

